jsonTools.init:
function init(eli) {
  var STORE = window.STORE_CONFIG || "config";
  var PENDING_PREFIX = "_survey_pending_";
  var RESPONSE_PREFIX = "_survey_response_";

  var ACCENT = "#c9a227";
  var ACCENT_DARK = "#a8851b";
  var BLUE = "#2563eb";
  var BLUE_DARK = "#1d4ed8";

  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }
  function _uid() { return Date.now().toString(36) + Math.random().toString(36).slice(2, 6); }
  function _toast(msg, type) { if (typeof showToast === "function") showToast(msg, type || "info"); }

  // Demo survey baked in so first-run has something to take.
  var DEMO_SURVEY = {
    id: "demo-onboarding-feedback",
    title: "Quick check on ELI",
    description: "Three short questions — should take under 30 seconds.",
    pushedAt: new Date().toISOString(),
    questions: [
      { id: "q1", type: "rating", label: "How likely are you to recommend ELI to a colleague?", min: 0, max: 10, required: true,
        hint: "0 = not at all, 10 = absolutely" },
      { id: "q2", type: "multiselect", label: "Which tools have saved you the most time?", options: [
        "Legal Review", "Build Draft", "Error Review", "Review Redlines", "Final Review", "Ask ELI", "Compare Doc",
      ], required: false },
      { id: "q3", type: "single", label: "How often do you open ELI?", options: ["Daily", "Weekly", "Monthly", "Rarely"], required: true },
      { id: "q4", type: "text", label: "Anything else you'd like to share?", placeholder: "Optional — what's working, what isn't…", multiline: true, required: false },
    ],
  };

  // ── Mount + chrome ────────────────────────────────────────────────
  function _mount() { return document.getElementById("_eli3_dashboard_root"); }

  function _renderShell(titleHtml, rightBtnsHtml) {
    var m = _mount();
    if (!m) { _toast("Dashboard root missing", "err"); return null; }
    m.innerHTML = "";
    var root = document.createElement("div");
    root.style.cssText = "background:#f1f5f9; min-height:100%; padding:0; font:500 13px/1.45 'Inter','Segoe UI',sans-serif; color:#0f172a;";
    root.innerHTML =
      '<div style="background:linear-gradient(180deg,#fff,#f8fafc); border-bottom:1px solid #e2e8f0; padding:14px 20px; display:flex; align-items:center; gap:12px; position:sticky; top:0; z-index:5;">' +
        '<button data-act="back" title="Back" style="border:1px solid #e2e8f0; background:#fff; border-radius:6px; padding:4px 10px; cursor:pointer; font-size:14px; color:#475569;">←</button>' +
        '<div style="font:700 15px/1 \'Inter\',sans-serif; color:#0f172a;">' + titleHtml + '</div>' +
        '<div style="flex:1"></div>' +
        (rightBtnsHtml || "") +
      '</div>' +
      '<div data-slot="body" style="padding:24px 28px; max-width:780px; margin:0 auto;"></div>';
    m.appendChild(root);
    var back = root.querySelector("[data-act='back']");
    if (back) back.onclick = function () {
      if (eli.dashboard && typeof eli.dashboard.goHome === "function") eli.dashboard.goHome();
    };
    return root.querySelector("[data-slot='body']");
  }

  // ── Storage helpers ───────────────────────────────────────────────
  function _allPending() {
    return eli.storage.getAll(STORE).then(function (rows) {
      return (rows || []).filter(function (r) {
        return r && typeof r.key === "string" && r.key.indexOf(PENDING_PREFIX) === 0;
      }).map(function (r) {
        var v = r.value || {}; v._key = r.key; return v;
      }).sort(function (a, b) {
        return String(b.pushedAt || "").localeCompare(String(a.pushedAt || ""));
      });
    }).catch(function () { return []; });
  }
  function _allResponses() {
    return eli.storage.getAll(STORE).then(function (rows) {
      return (rows || []).filter(function (r) {
        return r && typeof r.key === "string" && r.key.indexOf(RESPONSE_PREFIX) === 0;
      }).map(function (r) {
        var v = r.value || {}; v._key = r.key; return v;
      }).sort(function (a, b) {
        return String(b.submittedAt || "").localeCompare(String(a.submittedAt || ""));
      });
    }).catch(function () { return []; });
  }
  function _savePending(spec) {
    if (!spec || !spec.id) return Promise.reject(new Error("survey: missing id"));
    var row = Object.assign({ status: "pending", pushedAt: spec.pushedAt || new Date().toISOString() }, spec);
    return eli.storage.put(STORE, { key: PENDING_PREFIX + spec.id, value: row });
  }
  function _markStatus(surveyId, status) {
    var k = PENDING_PREFIX + surveyId;
    return eli.storage.get(STORE, k).then(function (row) {
      if (!row) return null;
      row.value = row.value || {};
      row.value.status = status;
      row.value.respondedAt = new Date().toISOString();
      return eli.storage.put(STORE, row);
    });
  }
  function _deletePending(id) { return eli.storage.delete(STORE, PENDING_PREFIX + id); }
  function _saveResponse(surveyId, answers) {
    var ts = Date.now();
    return eli.storage.put(STORE, { key: RESPONSE_PREFIX + surveyId + "_" + ts, value: {
      surveyId: surveyId, answers: answers, submittedAt: new Date().toISOString(),
    }});
  }
  function _relTime(iso) {
    if (!iso) return "just now";
    var t = new Date(iso).getTime();
    if (isNaN(t)) return iso;
    var d = Date.now() - t;
    if (d < 60000) return "just now";
    if (d < 3600000) return Math.floor(d / 60000) + " min ago";
    if (d < 86400000) return Math.floor(d / 3600000) + "h ago";
    return Math.floor(d / 86400000) + "d ago";
  }

  // ── Home panel ────────────────────────────────────────────────────
  function _renderHome() {
    // Telemetry — every other tool self-records its appOpened* stat from
    // the entry function. Kernel records `tile.id` only for trophy/bus
    // purposes; eli_telemetry's etDeriveToolName needs "appOpened" prefix.
    try { if (eli.stats && eli.stats.record) eli.stats.record("appOpenedSurveyTester"); } catch (_) {}
    var rightBtns =
      '<button data-act="seed" style="border:1px solid ' + ACCENT + '; background:linear-gradient(180deg,#fef3c7,#fde68a); color:#92400e; border-radius:6px; padding:7px 12px; cursor:pointer; font-weight:600; font-size:12.5px;">+ Push demo survey</button>' +
      '<button data-act="compose" style="border:1px solid ' + BLUE + '; background:linear-gradient(180deg,#3b82f6,' + BLUE + '); color:#fff; border-radius:6px; padding:7px 12px; cursor:pointer; font-weight:600; font-size:12.5px; margin-left:8px;">+ Custom survey</button>';
    var body = _renderShell("📋 Survey Tester", rightBtns);
    if (!body) return;

    body.innerHTML =
      '<div style="margin-bottom:24px;">' +
        '<div style="font:600 12px/1 \'Inter\',sans-serif; color:#64748b; text-transform:uppercase; letter-spacing:0.7px; margin-bottom:10px;">Pending</div>' +
        '<div data-slot="pending"></div>' +
      '</div>' +
      '<div>' +
        '<div style="font:600 12px/1 \'Inter\',sans-serif; color:#64748b; text-transform:uppercase; letter-spacing:0.7px; margin-bottom:10px;">Past responses</div>' +
        '<div data-slot="responses"></div>' +
      '</div>';

    var root = _mount();
    root.querySelector("[data-act='seed']").onclick = function () {
      var seed = Object.assign({}, DEMO_SURVEY, { id: DEMO_SURVEY.id + "-" + _uid(), pushedAt: new Date().toISOString() });
      _savePending(seed).then(function () { _toast("Demo survey pushed.", "ok"); _renderHome(); });
    };
    root.querySelector("[data-act='compose']").onclick = _renderComposer;

    _paintPending(body.querySelector("[data-slot='pending']"));
    _paintResponses(body.querySelector("[data-slot='responses']"));
  }

  function _paintPending(slot) {
    slot.innerHTML = '<div style="color:#94a3b8; font-style:italic;">Loading…</div>';
    _allPending().then(function (list) {
      if (!list.length) {
        slot.innerHTML = '<div style="border:1px dashed #cbd5e1; background:#fff; border-radius:10px; padding:24px; color:#64748b; text-align:center;">No pending surveys. Click <b>Push demo survey</b> to seed one.</div>';
        return;
      }
      slot.innerHTML = "";
      list.forEach(function (s) {
        var done = s.status === "completed";
        var card = document.createElement("div");
        card.style.cssText = "border:1px solid " + (done ? "#86efac" : "#e2e8f0") + "; background:" + (done ? "#f0fdf4" : "#fff") + "; border-radius:10px; padding:16px 18px; margin-bottom:10px; display:flex; align-items:center; gap:14px; box-shadow:0 1px 2px rgba(15,23,42,0.04);";
        card.innerHTML =
          '<div style="flex:1; min-width:0;">' +
            '<div style="font:600 14.5px/1.3 \'Inter\',sans-serif; color:#0f172a;">' + _esc(s.title || "(untitled survey)") + (done ? ' <span style="font-size:11px; color:#15803d; font-weight:700; margin-left:6px;">✓ COMPLETED</span>' : '') + '</div>' +
            '<div style="font-size:12px; color:#64748b; margin-top:5px;">' + (s.questions || []).length + ' question' + ((s.questions||[]).length === 1 ? '' : 's') + ' · pushed ' + _esc(_relTime(s.pushedAt)) + '</div>' +
            (s.description ? '<div style="font-size:12.5px; color:#475569; margin-top:8px;">' + _esc(s.description) + '</div>' : '') +
          '</div>' +
          '<div style="display:flex; gap:6px; flex-shrink:0; align-items:center;">' +
            (done
              ? '<button data-act="retake" style="border:1px solid #cbd5e1; background:#fff; color:#475569; border-radius:6px; padding:7px 11px; cursor:pointer; font-size:12px;">Retake</button>'
              : '<button data-act="take" style="border:1px solid ' + BLUE_DARK + '; background:linear-gradient(180deg,#3b82f6,' + BLUE + '); color:#fff; border-radius:6px; padding:8px 14px; cursor:pointer; font-weight:600; font-size:12.5px;">Take →</button>'
            ) +
            '<button data-act="del" title="Delete" style="border:1px solid #fecaca; background:#fff; color:#b91c1c; border-radius:6px; padding:7px 9px; cursor:pointer; font-size:12px;">✕</button>' +
          '</div>';
        var takeBtn = card.querySelector("[data-act='take'], [data-act='retake']");
        if (takeBtn) takeBtn.onclick = function () { _renderTake(s); };
        card.querySelector("[data-act='del']").onclick = function () {
          _deletePending(s.id).then(function () { _paintPending(slot); });
        };
        slot.appendChild(card);
      });
    });
  }

  function _paintResponses(slot) {
    _allResponses().then(function (list) {
      if (!list.length) {
        slot.innerHTML = '<div style="color:#94a3b8; font-style:italic; font-size:12.5px;">No responses yet.</div>';
        return;
      }
      slot.innerHTML = "";
      list.forEach(function (r) {
        var card = document.createElement("div");
        card.style.cssText = "border:1px solid #e2e8f0; background:#fff; border-radius:10px; padding:14px 16px; margin-bottom:8px;";
        var summary = (r.answers || []).map(function (a) {
          var v = Array.isArray(a.value) ? a.value.join(", ") : String(a.value == null ? "(empty)" : a.value);
          return '<div style="font-size:12px; color:#334155; margin-top:5px;"><span style="color:#94a3b8;">' + _esc(a.label || a.id) + ':</span> <b style="color:#0f172a;">' + _esc(v) + '</b></div>';
        }).join("");
        card.innerHTML =
          '<div style="display:flex; align-items:center; gap:10px;">' +
            '<div style="font:600 13px/1 \'Inter\',sans-serif; color:#0f172a; flex:1;">' + _esc(r.surveyId) + '</div>' +
            '<div style="font-size:11px; color:#94a3b8;">' + _esc(_relTime(r.submittedAt)) + '</div>' +
            '<button data-act="del-resp" title="Delete response" style="border:1px solid #fecaca; background:#fff; color:#b91c1c; border-radius:5px; padding:3px 7px; cursor:pointer; font-size:11px;">✕</button>' +
          '</div>' + summary;
        card.querySelector("[data-act='del-resp']").onclick = function () {
          eli.storage.delete(STORE, r._key).then(function () { _paintResponses(slot); });
        };
        slot.appendChild(card);
      });
    });
  }

  // ── Take Survey: full-panel one-question-at-a-time runner ─────────
  function _renderTake(survey) {
    var qs = (survey.questions || []).slice();
    if (!qs.length) { _toast("Survey has no questions.", "err"); return; }
    var idx = 0;
    var state = {}; // qid → value

    var body = _renderShell("📋 " + _esc(survey.title || "Survey"), "");
    if (!body) return;
    body.innerHTML =
      '<div data-slot="progress" style="margin-bottom:24px;"></div>' +
      (survey.description ? '<div style="font-size:12.5px; color:#64748b; margin-bottom:24px;">' + _esc(survey.description) + '</div>' : '') +
      '<div data-slot="q" style="background:#fff; border:1px solid #e2e8f0; border-radius:14px; padding:28px 32px; box-shadow:0 1px 3px rgba(15,23,42,0.04);"></div>' +
      '<div data-slot="nav" style="display:flex; gap:10px; margin-top:24px; align-items:center;"></div>';

    function _paint() {
      _paintProgress(body.querySelector("[data-slot='progress']"));
      _paintQuestion(body.querySelector("[data-slot='q']"));
      _paintNav(body.querySelector("[data-slot='nav']"));
    }
    function _paintProgress(el) {
      var pct = Math.round(((idx + 1) / qs.length) * 100);
      el.innerHTML =
        '<div style="display:flex; justify-content:space-between; font-size:11px; color:#94a3b8; text-transform:uppercase; letter-spacing:0.7px; font-weight:600; margin-bottom:6px;">' +
          '<span>Question ' + (idx + 1) + ' of ' + qs.length + '</span>' +
          '<span>' + pct + '%</span>' +
        '</div>' +
        '<div style="height:6px; background:#e2e8f0; border-radius:3px; overflow:hidden;">' +
          '<div style="height:100%; width:' + pct + '%; background:linear-gradient(90deg,' + BLUE + ',' + ACCENT + '); transition:width 0.3s ease;"></div>' +
        '</div>';
    }
    function _paintQuestion(el) {
      var q = qs[idx];
      el.innerHTML = "";
      var lbl = document.createElement("div");
      lbl.style.cssText = "font:600 17px/1.4 'Inter',sans-serif; color:#0f172a; margin-bottom:6px;";
      lbl.innerHTML = _esc(q.label) + (q.required ? ' <span style="color:#b91c1c; font-weight:700;">*</span>' : '');
      el.appendChild(lbl);
      if (q.hint) {
        var hint = document.createElement("div");
        hint.style.cssText = "font-size:12.5px; color:#64748b; margin-bottom:18px;";
        hint.textContent = q.hint;
        el.appendChild(hint);
      } else {
        var spacer = document.createElement("div");
        spacer.style.cssText = "height:12px;";
        el.appendChild(spacer);
      }
      _renderInput(q, state, el);
    }
    function _paintNav(el) {
      el.innerHTML = "";
      var back = document.createElement("button");
      back.textContent = "← Back";
      back.style.cssText = "border:1px solid #cbd5e1; background:#fff; color:#475569; border-radius:6px; padding:9px 16px; cursor:pointer; font-weight:600; font-size:13px;" + (idx === 0 ? " visibility:hidden;" : "");
      back.onclick = function () { if (idx > 0) { idx--; _paint(); } };
      el.appendChild(back);
      var spacer = document.createElement("div");
      spacer.style.cssText = "flex:1;";
      el.appendChild(spacer);
      var skip = document.createElement("button");
      skip.textContent = "Cancel";
      skip.style.cssText = "border:1px solid transparent; background:transparent; color:#64748b; padding:9px 12px; cursor:pointer; font-size:13px; margin-right:6px;";
      skip.onclick = _renderHome;
      el.appendChild(skip);
      var fwd = document.createElement("button");
      var isLast = idx === qs.length - 1;
      fwd.textContent = isLast ? "Submit ✓" : "Next →";
      fwd.style.cssText = "border:1px solid " + (isLast ? "#15803d" : BLUE_DARK) + "; background:linear-gradient(180deg," + (isLast ? "#22c55e,#15803d" : "#3b82f6," + BLUE) + "); color:#fff; border-radius:6px; padding:10px 22px; cursor:pointer; font-weight:700; font-size:13.5px;";
      fwd.onclick = function () {
        var q = qs[idx];
        var v = state[q.id];
        var empty = v == null || v === "" || (Array.isArray(v) && !v.length);
        if (q.required && empty) { _toast("This one's required.", "warn"); return; }
        if (isLast) {
          var answers = qs.map(function (qq) {
            var vv = state[qq.id];
            var em = vv == null || vv === "" || (Array.isArray(vv) && !vv.length);
            return { id: qq.id, label: qq.label, type: qq.type, value: em ? null : vv };
          });
          _saveResponse(survey.id, answers).then(function () {
            return _markStatus(survey.id, "completed");
          }).then(function () {
            _renderThanks(survey);
          });
        } else {
          idx++; _paint();
        }
      };
      el.appendChild(fwd);
    }
    _paint();
  }

  function _renderInput(q, state, host) {
    if (q.type === "rating") {
      var min = q.min != null ? q.min : 1;
      var max = q.max != null ? q.max : 5;
      var row = document.createElement("div");
      row.style.cssText = "display:flex; gap:8px; flex-wrap:wrap; margin-top:6px;";
      var buttons = [];
      for (var i = min; i <= max; i++) {
        (function (val) {
          var b = document.createElement("button");
          b.type = "button";
          b.textContent = String(val);
          b.style.cssText = "min-width:46px; height:46px; border:1px solid #cbd5e1; background:#fff; color:#0f172a; border-radius:8px; cursor:pointer; font-weight:600; font-size:15px; transition:all 0.15s ease;";
          b.onmouseenter = function () { if (state[q.id] !== val) b.style.borderColor = BLUE; };
          b.onmouseleave = function () { if (state[q.id] !== val) b.style.borderColor = "#cbd5e1"; };
          b.onclick = function () {
            state[q.id] = val;
            buttons.forEach(function (x) {
              x.btn.style.background = "#fff"; x.btn.style.color = "#0f172a"; x.btn.style.borderColor = "#cbd5e1";
            });
            b.style.background = BLUE; b.style.color = "#fff"; b.style.borderColor = BLUE_DARK;
          };
          buttons.push({ btn: b, val: val });
          row.appendChild(b);
        })(i);
      }
      if (state[q.id] != null) {
        var hit = buttons.filter(function (x) { return x.val === state[q.id]; })[0];
        if (hit) { hit.btn.style.background = BLUE; hit.btn.style.color = "#fff"; hit.btn.style.borderColor = BLUE_DARK; }
      }
      host.appendChild(row);
    } else if (q.type === "multiselect") {
      if (!Array.isArray(state[q.id])) state[q.id] = [];
      (q.options || []).forEach(function (opt) {
        var on = state[q.id].indexOf(opt) !== -1;
        var row = document.createElement("div");
        row.style.cssText = "display:flex; align-items:center; gap:10px; padding:11px 14px; border:1px solid " + (on ? BLUE : "#e2e8f0") + "; background:" + (on ? "#eff6ff" : "#fff") + "; border-radius:8px; cursor:pointer; margin-bottom:8px; transition:all 0.12s ease;";
        var box = document.createElement("div");
        box.style.cssText = "width:18px; height:18px; border:2px solid " + (on ? BLUE : "#cbd5e1") + "; background:" + (on ? BLUE : "#fff") + "; border-radius:4px; display:flex; align-items:center; justify-content:center; color:#fff; font-size:11px; font-weight:700; flex-shrink:0;";
        box.textContent = on ? "✓" : "";
        var lbl = document.createElement("div");
        lbl.style.cssText = "flex:1; font-size:13.5px; color:#0f172a;";
        lbl.textContent = opt;
        row.appendChild(box); row.appendChild(lbl);
        row.onclick = function () {
          var i = state[q.id].indexOf(opt);
          if (i === -1) state[q.id].push(opt);
          else state[q.id].splice(i, 1);
          var nowOn = state[q.id].indexOf(opt) !== -1;
          row.style.borderColor = nowOn ? BLUE : "#e2e8f0";
          row.style.background = nowOn ? "#eff6ff" : "#fff";
          box.style.borderColor = nowOn ? BLUE : "#cbd5e1";
          box.style.background = nowOn ? BLUE : "#fff";
          box.textContent = nowOn ? "✓" : "";
        };
        host.appendChild(row);
      });
    } else if (q.type === "single") {
      (q.options || []).forEach(function (opt) {
        var on = state[q.id] === opt;
        var row = document.createElement("div");
        row.style.cssText = "display:flex; align-items:center; gap:10px; padding:11px 14px; border:1px solid " + (on ? BLUE : "#e2e8f0") + "; background:" + (on ? "#eff6ff" : "#fff") + "; border-radius:8px; cursor:pointer; margin-bottom:8px; transition:all 0.12s ease;";
        var dot = document.createElement("div");
        dot.style.cssText = "width:18px; height:18px; border:2px solid " + (on ? BLUE : "#cbd5e1") + "; border-radius:50%; display:flex; align-items:center; justify-content:center; flex-shrink:0;";
        if (on) { var inner = document.createElement("div"); inner.style.cssText = "width:10px; height:10px; background:" + BLUE + "; border-radius:50%;"; dot.appendChild(inner); }
        var lbl = document.createElement("div");
        lbl.style.cssText = "flex:1; font-size:13.5px; color:#0f172a;";
        lbl.textContent = opt;
        row.appendChild(dot); row.appendChild(lbl);
        row.onclick = function () {
          state[q.id] = opt;
          // Re-render group to update visual state of all radios.
          var parent = host;
          host.innerHTML = "";
          _renderInput(q, state, parent);
        };
        host.appendChild(row);
      });
    } else { // text
      var inp;
      if (q.multiline) {
        inp = document.createElement("textarea");
        inp.style.cssText = "width:100%; min-height:110px; padding:12px 14px; border:1px solid #cbd5e1; border-radius:8px; font:inherit; font-size:13.5px; box-sizing:border-box; resize:vertical;";
      } else {
        inp = document.createElement("input");
        inp.type = "text";
        inp.style.cssText = "width:100%; padding:12px 14px; border:1px solid #cbd5e1; border-radius:8px; font:inherit; font-size:13.5px; box-sizing:border-box;";
      }
      if (q.placeholder) inp.placeholder = q.placeholder;
      if (state[q.id] != null) inp.value = state[q.id];
      inp.oninput = function () { state[q.id] = inp.value; };
      inp.onfocus = function () { inp.style.borderColor = BLUE; inp.style.boxShadow = "0 0 0 3px rgba(37,99,235,0.12)"; };
      inp.onblur = function () { inp.style.borderColor = "#cbd5e1"; inp.style.boxShadow = "none"; };
      host.appendChild(inp);
    }
  }

  // ── Thank-you panel after submit ──────────────────────────────────
  function _renderThanks(survey) {
    var body = _renderShell("📋 " + _esc(survey.title || "Survey"), "");
    if (!body) return;
    body.innerHTML =
      '<div style="background:#fff; border:1px solid #86efac; border-radius:14px; padding:48px 32px; text-align:center; box-shadow:0 1px 3px rgba(15,23,42,0.04);">' +
        '<div style="font-size:48px; margin-bottom:14px;">✅</div>' +
        '<div style="font:700 20px/1.3 \'Inter\',sans-serif; color:#0f172a; margin-bottom:8px;">Thanks for the feedback!</div>' +
        '<div style="font-size:13.5px; color:#475569; margin-bottom:28px;">Your response has been saved.</div>' +
        '<button data-act="home" style="border:1px solid ' + BLUE_DARK + '; background:linear-gradient(180deg,#3b82f6,' + BLUE + '); color:#fff; border-radius:6px; padding:10px 22px; cursor:pointer; font-weight:600; font-size:13.5px;">Back to surveys</button>' +
      '</div>';
    body.querySelector("[data-act='home']").onclick = _renderHome;
  }

  // ── Composer panel ────────────────────────────────────────────────
  function _renderComposer() {
    var body = _renderShell("✏️ Compose test survey", "");
    if (!body) return;
    body.innerHTML =
      '<div style="background:#fff; border:1px solid #e2e8f0; border-radius:14px; padding:24px 28px; box-shadow:0 1px 3px rgba(15,23,42,0.04);">' +
        '<div style="font-size:12.5px; color:#475569; margin-bottom:14px; line-height:1.5;">Paste a JSON survey spec, or click <b>Use template</b> to start from the demo. After saving, the survey appears in <b>Pending</b> just like an admin-pushed one.</div>' +
        '<div style="display:flex; gap:8px; margin-bottom:12px;">' +
          '<button data-act="tmpl" style="border:1px solid #cbd5e1; background:#fff; color:#475569; border-radius:6px; padding:6px 12px; cursor:pointer; font-size:12px; font-weight:600;">Use template</button>' +
          '<button data-act="clear" style="border:1px solid #cbd5e1; background:#fff; color:#475569; border-radius:6px; padding:6px 12px; cursor:pointer; font-size:12px;">Clear</button>' +
        '</div>' +
        '<textarea data-slot="spec" spellcheck="false" style="width:100%; min-height:340px; padding:14px; border:1px solid #cbd5e1; border-radius:8px; font:12px/1.5 \'SF Mono\',\'Consolas\',\'Monaco\',monospace; box-sizing:border-box; color:#0f172a;"></textarea>' +
        '<div data-slot="err" style="color:#b91c1c; font-size:12.5px; margin-top:10px; min-height:18px; font-weight:600;"></div>' +
        '<div style="display:flex; gap:10px; margin-top:16px; justify-content:flex-end;">' +
          '<button data-act="cancel" style="border:1px solid #cbd5e1; background:#fff; color:#475569; border-radius:6px; padding:9px 16px; cursor:pointer; font-weight:600; font-size:13px;">Cancel</button>' +
          '<button data-act="save" style="border:1px solid ' + BLUE_DARK + '; background:linear-gradient(180deg,#3b82f6,' + BLUE + '); color:#fff; border-radius:6px; padding:9px 18px; cursor:pointer; font-weight:600; font-size:13px;">Save as pending</button>' +
        '</div>' +
      '</div>' +
      '<div style="margin-top:18px; padding:14px 18px; background:#f1f5f9; border-radius:10px; font-size:11.5px; color:#475569; line-height:1.5;">' +
        '<b style="color:#0f172a;">Schema:</b> ' +
        '<code style="background:#fff; padding:1px 5px; border-radius:3px;">{ id?, title, description?, questions: [{ id, type, label, required?, … }] }</code><br>' +
        '<b style="color:#0f172a; margin-top:6px; display:inline-block;">Types:</b> ' +
        '<code style="background:#fff; padding:1px 5px; border-radius:3px;">rating</code> (min/max), ' +
        '<code style="background:#fff; padding:1px 5px; border-radius:3px;">multiselect</code> (options[]), ' +
        '<code style="background:#fff; padding:1px 5px; border-radius:3px;">single</code> (options[]), ' +
        '<code style="background:#fff; padding:1px 5px; border-radius:3px;">text</code> (placeholder, multiline)' +
      '</div>';
    var ta = body.querySelector("[data-slot='spec']");
    var errEl = body.querySelector("[data-slot='err']");
    body.querySelector("[data-act='tmpl']").onclick = function () { ta.value = JSON.stringify(DEMO_SURVEY, null, 2); };
    body.querySelector("[data-act='clear']").onclick = function () { ta.value = ""; errEl.textContent = ""; };
    body.querySelector("[data-act='cancel']").onclick = _renderHome;
    body.querySelector("[data-act='save']").onclick = function () {
      var raw = ta.value.trim();
      errEl.textContent = "";
      if (!raw) { errEl.textContent = "Paste a survey JSON first."; return; }
      var spec;
      try { spec = JSON.parse(raw); }
      catch (e) { errEl.textContent = "Invalid JSON: " + e.message; return; }
      if (!spec || !Array.isArray(spec.questions) || !spec.questions.length) {
        errEl.textContent = "Spec needs a questions[] array."; return;
      }
      if (!spec.id) spec.id = "custom-" + _uid();
      spec.pushedAt = new Date().toISOString();
      _savePending(spec).then(function () { _toast("Saved as pending.", "ok"); _renderHome(); });
    };
  }

  // ── Public dispatch surface ───────────────────────────────────────
  function _pushFromAdmin(spec) {
    if (!spec || typeof spec !== "object") return Promise.reject(new Error("survey: spec required"));
    var s = Object.assign({}, spec);
    if (!s.id) s.id = "pushed-" + _uid();
    s.pushedAt = s.pushedAt || new Date().toISOString();
    return _savePending(s).then(function () {
      try { _toast("📋 New survey: " + (s.title || "(untitled)"), "info"); } catch (_e) {}
      return true;
    });
  }

  eli.register({
    tile: { app_survey_tester: _renderHome },
    survey: { open: _renderHome, push: _pushFromAdmin },
  });

  eli.log.event("tool", "survey_tester_initialized", {});
}
